using Azure.Messaging.ServiceBus;using Azure.Storage.Blobs;using EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;using System.Text.Json;
public sealed class ServiceBusClientFactory(IConfiguration c){readonly ServiceBusClient client=!string.IsNullOrWhiteSpace(c["ServiceBus:ConnectionString"])?new(c["ServiceBus:ConnectionString"]!):new(c["ServiceBus:FullyQualifiedNamespace"]!,new Azure.Identity.DefaultAzureCredential());public ServiceBusProcessor Create(string t,string s)=>client.CreateProcessor(t,s,new ServiceBusProcessorOptions{MaxConcurrentCalls=8,PrefetchCount=50,AutoCompleteMessages=false});}
public sealed class Worker(ServiceBusClientFactory factory,BlobServiceClient blobs,IDocumentTextExtractor extractor,IMessagePublisher publisher,ILogger<Worker> log,IConfiguration config):BackgroundService{protected override async Task ExecuteAsync(CancellationToken ct){var p=factory.Create(Topics.DocumentEvents,"ingestion-sub");p.ProcessMessageAsync+=Handle;p.ProcessErrorAsync+=Error;await p.StartProcessingAsync(ct);try{await Task.Delay(Timeout.Infinite,ct);}catch(OperationCanceledException){}finally{await p.StopProcessingAsync();await p.DisposeAsync();}}async Task Handle(ProcessMessageEventArgs a){try{var m=JsonSerializer.Deserialize<DocumentUploaded>(a.Message.Body.ToString(),new(JsonSerializerDefaults.Web))??throw new InvalidOperationException("Invalid DocumentUploaded event");var client=new BlobClient(new Uri(m.BlobUri),new Azure.Identity.DefaultAzureCredential());await using var content=await client.OpenReadAsync(cancellationToken:a.CancellationToken);var text=await extractor.ExtractAsync(content,m.ContentType,a.CancellationToken);var container=blobs.GetBlobContainerClient("extracted");await container.CreateIfNotExistsAsync(cancellationToken:a.CancellationToken);var target=container.GetBlobClient($"{m.TenantId}/{m.DocumentId}/{m.VersionId}.txt");await using var stream=new MemoryStream(System.Text.Encoding.UTF8.GetBytes(text));await target.UploadAsync(stream,overwrite:true,a.CancellationToken);await publisher.PublishAsync(Topics.IngestionEvents,new DocumentIngestionCompleted(Guid.NewGuid(),m.TenantId,m.DocumentId,m.VersionId,target.Uri.ToString(),DateTimeOffset.UtcNow,m.CorrelationId),m.CorrelationId,a.CancellationToken);await a.CompleteMessageAsync(a.Message);}catch(Exception ex){log.LogError(ex,"Ingestion failed MessageId={MessageId}",a.Message.MessageId);if(a.Message.DeliveryCount>=5)await a.DeadLetterMessageAsync(a.Message,"max-delivery",ex.Message);else await a.AbandonMessageAsync(a.Message);}}Task Error(ProcessErrorEventArgs e){log.LogError(e.Exception,"Ingestion Service Bus error {Entity}",e.EntityPath);return Task.CompletedTask;}}